export function translateText(value, language) {
  if (!value || language === 'en') return value;
  // JSX commonly preserves indentation/newlines in text nodes. Matching a
  // normalized key keeps translations stable regardless of component layout.
  const entry = translations[value.trim().replace(/\s+/g, ' ')];
  if (!entry) return value;
  const index = { fr: 0, de: 1, es: 2 }[language];
  const translated = entry[index];
  const leading = value.match(/^\s*/)?.[0] ?? '';
  const trailing = value.match(/\s*$/)?.[0] ?? '';
  return `${leading}${translated}${trailing}`;
}
